def release(key, how_many \\ 1) do
  Enum.reduce_while(1..how_many, :ok, fn _, :ok ->
    case :ets.select_replace(__MODULE__, [
           {{:"$1", :"$2", :"$3", :"$4"},
            [{:andalso, {:==, :"$1", key}, {:"=<", {:+, :"$3", 1}, :"$2"}}],
            [{{:"$1", :"$2", {:+, :"$3", 1}, :"$4"}}]}
         ]) do
      0 -> {:halt, :error}
      1 -> {:cont, :ok}
    end
  end)
end

def error(reactor, reason, context) do
  Enum.reduce(reactor.middleware, {:error, reason}, fn middleware, {:error, reason} ->
    with true <- function_exported?(middleware, :error, 2),
         {:error, reason} <- middleware.error(reason, context) do
      {:error, reason}
    else
      _ -> {:error, reason}
    end
  end)
end

def init(attrs \\ %{}) do
  @defaults |> Map.merge(attrs) |> do_init()
end

def and_then({:ok, input}, transform) when is_function(transform, 1) do
  case transform.(input) do
    {:ok, output} -> {:ok, output}
    {:error, reason} -> {:error, reason}
  end
end
def and_then({:error, reason}, _transform) do
  {:error, reason}
end

def map_while_ok(inputs, mapper, preserve_order? \\ false)
def map_while_ok(inputs, mapper, false) when is_function(mapper, 1) do
  reduce_while_ok(inputs, [], fn input, acc ->
    case mapper.(input) do
      {:ok, value} -> {:ok, [value | acc]}
      {:error, reason} -> {:error, reason}
    end
  end)
end
def map_while_ok(inputs, mapper, true) do
  case map_while_ok(inputs, mapper, false) do
    {:ok, outputs} -> {:ok, Enum.reverse(outputs)}
    {:error, reason} -> {:error, reason}
  end
end

def reduce_while_ok(inputs, default \\ [], reducer) when is_function(reducer, 2) do
  Enum.reduce_while(inputs, {:ok, default}, fn input, {:ok, acc} ->
    case reducer.(input, acc) do
      {:ok, acc} -> {:cont, {:ok, acc}}
      {:error, reason} -> {:halt, {:error, reason}}
    end
  end)
end

