end
def split_module_and_func(call, current_module, aliases) do
  case Code.string_to_quoted(call, emit_warnings: false) do
    {:error, _} -> {nil, nil}
    {:ok, quoted} when is_atom(quoted) -> {quoted, nil}
    {:ok, quoted} -> split_mod_quoted_fun_call(quoted, current_module, aliases)
  end
end

