def handle_sqs_results(
      {:error,
       {:http_error, http_status, %{code: code, message: message, request_id: request_id}}}
    ) do
  Logger.error(
    "SQS request HTTP error: http_status=#{http_status} code=#{code}, message=#{message}, request_id=#{request_id}"
  )

  {:ok, []}
end
def handle_sqs_results({:error, error}) do
  Logger.error("SQS request error: error=#{inspect(error)}")
  {:ok, []}
end
def handle_sqs_results({:ok, %{body: %{messages: []}, status_code: 200}}) do
  Logger.info("Received SQS messages, count=0")
  {:ok, []}
end
def handle_sqs_results({:ok, %{body: %{messages: messages}, status_code: 200}})
    when is_list(messages) do
  Logger.info("Received SQS messages, count=#{length(messages)}")
  {:ok, Enum.map(messages, &parse_message/1)}
end

