  route_id = mbta_id(route)
  silver_line_rapid_transit_ids = ~w(741 742 743 746)

  if route_id in silver_line_rapid_transit_ids do
    {:silver_line, leg.from.name, leg.to.name}
  else
    {leg.route.type, leg.from.name, leg.to.name}
  end
end
