def translate_opts(opts) do
  Keyword.new(opts, fn {opt, value} ->
    case @arg_types[opt] do
      {:string, :atom} -> {opt, String.to_atom(value)}
      {:string, :binary} -> {opt, decode_binary_opt(value)}
      {type, type} -> {opt, value}
    end
  end)
end

def error_if_nil(nil, reason) do
  {:error, reason}
end
def error_if_nil(v, _reason) do
  {:ok, v}
end

def stateful_try_with_status({:ok, _state} = res) do
  {:ok, res}
end
def stateful_try_with_status({{:ok, _res}, _state} = res) do
  {:ok, res}
end
def stateful_try_with_status({{:error, reason}, _state} = res) do
  {{:error, reason}, res}
end

