@spec stateful_try_with_status(result) :: {status, result} when [
  status: Type.try_t(),
  result: Type.stateful_try_t(state :: any) | Type.stateful_try_t(value :: any, state :: any)
]

@spec parse(config :: Keyword.t(v), [field | {field, field_specs | (parsed_config -> field_specs)}]) :: Type.try_t(parsed_config, reason) when [
  parsed_config: %{atom() => v},
  field: atom(),
  v: any(),
  field_specs:
    [
      validate:
        (v | any() -> Type.try_t() | boolean())
        | (v | any(), parsed_config -> Type.try_t() | boolean()),
      in: Enumerable.t(),
      default: v,
      require?: boolean(),
      require_if: (parsed_config -> boolean())
    ]
    | nil,
  reason:
    {:config_not_keyword, any()}
    | {:config_duplicates, [atom()]}
    | {:config_invalid_keys, [atom()]}
    | {:config_field,
       {:key_not_found, atom()}
       | {:invalid_value, key: atom(), value: any()}
       | {:invalid_value, key: atom(), value: any(), reason: {:not_in, Enumerable.t()} | any()}}
]

