def transform_element_children(nodes, transform) do
  Enum.map(nodes, fn
    {tag, attributes, children, meta} -> {tag, attributes, transform.(children), meta}
    {:block, name, expr, children, meta} -> {:block, name, expr, transform.(children), meta}
    node -> node
  end)
end

