def command(cluster, command, opts \\ []) when is_atom(cluster) do
  with {:ok, [result]} <- execute_pipeline(cluster, [command], opts) do
    case result do
      %Redix.Error{} = error -> {:error, error}
      %Redix.ConnectionError{} = error -> {:error, error}
      other -> {:ok, other}
    end
  end
end

