def get_connection_by_node(registry, {host, port}) do
  guard_missing_table(
    fn -> lookup_connection(registry, canonical_node_id(host, port)) end,
    :error
  )
end

def ping(conn, timeout \\ 5000)
    when (is_integer(timeout) and timeout >= 0) or timeout == :infinity do
  :gen_statem.call(conn, :ping, timeout)
catch
  :exit, {:timeout, _} -> {:error, %ConnectionError{reason: :timeout}}
end

def get(key) do
  case :ets.lookup(:statix_conn_tracker, key) do
    [{^key, [_ | _] = connections}] -> {:ok, Enum.random(connections)}
    _ -> {:error, :not_found}
  end
end
